using System.Net;
namespace PurpleStream;
record JobStatus(string State,long Bytes=0,long Total=0,string Detail="");
sealed class TransferJob {
 public Guid Id{get;}=Guid.NewGuid();public string Name{get;}public string Type{get;}public string File{get;internal set;}public string Partial{get;internal set;}public CancellationTokenSource Cancellation{get;}=new();public Task? Work{get;internal set;}JobStatus current=new("Queued");
 public JobStatus Status=>Volatile.Read(ref current);public bool Active=>Status.State is "Queued" or "Downloading" or "Connecting" or "Recording" or "Finalizing";
 public TransferJob(string name,string type,string file){Name=name;Type=type;File=file;Partial=file+".part";}public void Update(JobStatus value)=>Volatile.Write(ref current,value);public void Stop()=>Cancellation.Cancel();
}
sealed class TransferManager:IDisposable {
 readonly HttpClient http;readonly List<TransferJob> jobs=new();public IReadOnlyList<TransferJob> Jobs=>jobs;
 public TransferManager(HttpMessageHandler? handler=null){http=new HttpClient(handler??new HttpClientHandler{AutomaticDecompression=DecompressionMethods.All}){Timeout=Timeout.InfiniteTimeSpan};http.DefaultRequestHeaders.UserAgent.ParseAdd("PurpleStream/0.4");}
 public static string SafeName(string name){var invalid=Path.GetInvalidFileNameChars();var result=new string(name.Select(c=>invalid.Contains(c)||char.IsControl(c)?'_':c).ToArray()).Trim().TrimEnd('.');if(result.Length==0)result="Video";return result[..Math.Min(result.Length,100)];}
 static string Unique(string folder,string name,string extension){Directory.CreateDirectory(folder);string path=Path.Combine(folder,SafeName(name)+" "+DateTime.Now.ToString("yyyyMMdd-HHmmss")+"-"+Guid.NewGuid().ToString("N")[..6]+extension);return path;}
 public TransferJob Download(Channel media,string folder){if(media.Kind is "Live TV" or "Series")throw new ProviderFailure("Choose a movie or an individual episode to download.");var uri=new Uri(media.Url);if(uri.Scheme is not ("http" or "https"))throw new ProviderFailure("Downloads require an HTTP(S) stream.");bool segmented=uri.AbsolutePath.EndsWith(".m3u8",StringComparison.OrdinalIgnoreCase)||uri.AbsolutePath.EndsWith(".mpd",StringComparison.OrdinalIgnoreCase);if(segmented)return Capture(media,folder,false);
 string ext=Path.GetExtension(uri.AbsolutePath);if(ext.Length<2||ext.Length>8||ext.Any(c=>!char.IsAsciiLetterOrDigit(c)&&c!='.'))ext=".mp4";var job=new TransferJob(media.Name,"Download",Unique(folder,media.Name,ext));jobs.Add(job);job.Work=Task.Run(()=>DownloadTo(job,media.Url));return job;}
 public async Task DownloadTo(TransferJob job,string url){try{job.Update(new("Downloading"));using var timeout=CancellationTokenSource.CreateLinkedTokenSource(job.Cancellation.Token);timeout.CancelAfter(TimeSpan.FromMinutes(3));using var response=await http.GetAsync(url,HttpCompletionOption.ResponseHeadersRead,timeout.Token).ConfigureAwait(false);response.EnsureSuccessStatusCode();string type=response.Content.Headers.ContentType?.MediaType??"";if(type.Contains("html")||type.Contains("json")||type.Contains("mpegurl"))throw new ProviderFailure("The server returned a page or playlist instead of a downloadable video.");long total=response.Content.Headers.ContentLength??0;await using var input=await response.Content.ReadAsStreamAsync(timeout.Token).ConfigureAwait(false);await using(var output=new FileStream(job.Partial,FileMode.CreateNew,FileAccess.Write,FileShare.Read,128*1024,true)){byte[] buffer=new byte[128*1024];long size=0;while(true){timeout.CancelAfter(TimeSpan.FromMinutes(3));int count=await input.ReadAsync(buffer,timeout.Token).ConfigureAwait(false);if(count==0)break;await output.WriteAsync(buffer.AsMemory(0,count),timeout.Token).ConfigureAwait(false);size+=count;job.Update(new("Downloading",size,total));}await output.FlushAsync(timeout.Token).ConfigureAwait(false);if(size==0||(total>0&&size!=total))throw new IOException("Incomplete download.");}File.Move(job.Partial,job.File);job.Update(new("Completed",new FileInfo(job.File).Length,total));}
 catch(OperationCanceledException){job.Update(new(job.Cancellation.IsCancellationRequested?"Cancelled":"Failed",Detail:job.Cancellation.IsCancellationRequested?"Partial file retained":"Server timed out; partial file retained"));}catch{job.Update(new("Failed",Detail:"Download failed. Check provider access, disk space or connection. Partial files are not marked complete."));}}
 public TransferJob Capture(Channel media,string folder,bool live){var job=new TransferJob(media.Name,live?"Recording":"HLS download",Unique(folder,media.Name,".ts"));jobs.Add(job);job.Work=Task.Run(()=>CaptureTo(job,media.Url,live));return job;}
 async Task CaptureTo(TransferJob job,string url,bool live){using var engine=new AsyncPlayback(IntPtr.Zero);try{job.Update(new("Connecting"));engine.Play(url,0,output:job.Partial);var start=DateTime.UtcNow;bool began=false;while(!job.Cancellation.IsCancellationRequested){await Task.Delay(400);var state=engine.State;if(state.State==7)throw new IOException();long size=File.Exists(job.Partial)?new FileInfo(job.Partial).Length:0;if(state.State==3||size>0)began=true;if(!began&&DateTime.UtcNow-start>TimeSpan.FromSeconds(40))throw new TimeoutException();job.Update(new(live?"Recording":"Downloading",size,Detail:"Capturing to MPEG-TS"));if(state.State==6)break;}
 job.Update(new("Finalizing"));engine.Stop();engine.Dispose();await engine.Completion.WaitAsync(TimeSpan.FromSeconds(15));if(!File.Exists(job.Partial)||new FileInfo(job.Partial).Length==0)throw new IOException();File.Move(job.Partial,job.File);job.Update(new(live||!job.Cancellation.IsCancellationRequested?"Completed":"Cancelled",new FileInfo(job.File).Length));}
 catch{engine.Stop();job.Update(new("Failed",Detail:"Capture failed or could not finalize. Any partial file is retained."));}}
 public void Dispose(){foreach(var job in jobs.Where(j=>j.Active))job.Stop();http.Dispose();}
}
